"""HQECC(Q_n): build the hypercube graph and count logical qubits two ways."""
from __future__ import annotations
from typing import List, Tuple


def hypercube_edges(n: int) -> Tuple[int, List[Tuple[int, int]]]:
    V = 1 << n
    edges = [(v, v ^ (1 << b)) for v in range(V) for b in range(n)
             if v < (v ^ (1 << b))]
    return V, edges


def connected_components(V: int, edges: List[Tuple[int, int]]) -> int:
    parent = list(range(V))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        parent[find(u)] = find(v)
    return len({find(x) for x in range(V)})


def betti1_direct(n: int) -> int:
    V, edges = hypercube_edges(n)
    return len(edges) - V + connected_components(V, edges)


def betti1_closed(n: int) -> int:
    return (1 << (n - 1)) * (n - 2) + 1


if __name__ == "__main__":
    for n in range(1, 9):
        assert betti1_direct(n) == betti1_closed(n)
        print(f"Q_{n}: logical qubits = {betti1_closed(n)}")

