from typing import List

Matrix = List[List[int]]


def css_logical_dimension(d1: Matrix, d2: Matrix, dim_B: int) -> int:
    """Logical dimension k = dim(B) - rank(d1) - rank(d2) over F_2."""
    def rank_f2(m: Matrix) -> int:
        rows = [r[:] for r in m]
        if not rows or not rows[0]:
            return 0
        rank = 0
        for col in range(len(rows[0])):
            piv = next((r for r in range(rank, len(rows))
                        if rows[r][col] == 1), None)
            if piv is None:
                continue
            rows[rank], rows[piv] = rows[piv], rows[rank]
            for r in range(len(rows)):
                if r != rank and rows[r][col] == 1:
                    rows[r] = [a ^ b for a, b in zip(rows[r], rows[rank])]
            rank += 1
        return rank
    return dim_B - rank_f2(d1) - rank_f2(d2)
